import { useVehicle } from '@/app/axios';
import { useEffect, useState } from 'react';
import { useTranslations } from 'next-intl';
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '../ui/accordion';
import { Minus, Plus, Check } from 'lucide-react';
import { Checkbox } from '@/components/ui/checkbox';
import { cn } from '@/lib/utils';
import { BodyType } from '@/common/interfaces';

const CarFilter = () => {
  const t = useTranslations('carFilter');
  const { filterMetadata, fetchFilterMetadata, fetchVehicles, isLoading, error, clearError } = useVehicle();

  const [selectedModels, setSelectedModels] = useState<Record<string, string[]>>({}); // Category -> string[]
  const [isInitialized, setIsInitialized] = useState(false);

  useEffect(() => {
    fetchFilterMetadata();
  }, [fetchFilterMetadata]);

  useEffect(() => {
    if (filterMetadata && !isInitialized) {
      const initial: Record<string, string[]> = {};
      filterMetadata.bodyTypes.forEach((bt) => {
        initial[bt.bodyType] = bt.models;
      });
      filterMetadata.brands.forEach((b) => {
        initial[b.make] = b.models;
      });
      setSelectedModels(initial);
      setIsInitialized(true);
    }
  }, [filterMetadata, isInitialized]);

  useEffect(() => {
    if (isInitialized) {
      // Find all models that are selected across ALL categories
      // We need to send 'make' and 'model' arrays to backend
      const activeMakes: string[] = [];
      const activeBodyTypes: string[] = [];
      const activeModels: string[] = [];

      filterMetadata?.brands.forEach((b) => {
        const selectedForBrand = selectedModels[b.make] || [];
        if (selectedForBrand.length > 0) {
          activeMakes.push(b.make);
          activeModels.push(...selectedForBrand);
        }
      });

      filterMetadata?.bodyTypes.forEach((bt) => {
        const selectedForBT = selectedModels[bt.bodyType] || [];
        if (selectedForBT.length > 0) {
          activeBodyTypes.push(bt.bodyType);
          // models are already added via brands, but we filter by model anyway
        }
      });

      const timer = setTimeout(() => {
        fetchVehicles({
          bodyType: activeBodyTypes as BodyType[],
          make: activeMakes,
          model: [...new Set(activeModels)], // Unique models
        });
      }, 500);

      return () => clearTimeout(timer);
    }
  }, [selectedModels, fetchVehicles, isInitialized, filterMetadata]);

  const handleModelToggle = (category: string, model: string) => {
    setSelectedModels((prev) => {
      // Find all categories containing this model to keep them in sync
      const next = { ...prev };

      // We need to find if the model is currently selected in any category (it should be consistent)
      // Actually, let's find ALL categories that have this model
      const categoriesWithModel: string[] = [];
      filterMetadata?.bodyTypes.forEach((bt) => {
        if (bt.models.includes(model)) categoriesWithModel.push(bt.bodyType);
      });
      filterMetadata?.brands.forEach((b) => {
        if (b.models.includes(model)) categoriesWithModel.push(b.make);
      });

      const isSelected = prev[category]?.includes(model);

      categoriesWithModel.forEach((cat) => {
        const current = prev[cat] || [];
        if (isSelected) {
          next[cat] = current.filter((m) => m !== model);
        } else {
          next[cat] = [...current, model];
        }
      });

      return next;
    });
  };

  const renderFilterSection = (
    title: string,
    items: { label: string; count: number; models: string[] }[],
    type: 'bodyType' | 'brand',
  ) => {
    const selectedState = selectedModels;

    return (
      <div className="mb-8">
        <h4 className="mb-4 text-lg font-bold text-gray-900">{title}</h4>
        <Accordion type="multiple" className="w-full space-y-3">
          {items.map((item) => {
            const models = item.models || [];
            const activeModelsForCategory = selectedState[item.label] || [];

            return (
              <AccordionItem key={item.label} value={item.label} className="border-none">
                <AccordionTrigger className="cursor-pointer p-0 hover:no-underline [&[data-state=open]_.minus]:scale-100 [&[data-state=open]_.plus]:scale-0">
                  <div className="group flex w-full items-center justify-between">
                    <div className="flex flex-1 items-center gap-3">
                      <div className="relative flex h-5 w-5 cursor-pointer items-center justify-center rounded-[4px] bg-[#3B82F6] text-white">
                        <Plus className="plus absolute h-3.5 w-3.5 transition-transform duration-200" />
                        <Minus className="minus absolute h-3.5 w-3.5 scale-0 transition-transform duration-200" />
                      </div>

                      <span className="text-base font-medium text-gray-800 select-none">{item.label}</span>
                    </div>

                    <span className="text-base font-medium text-gray-800">[{item.count}]</span>
                  </div>
                </AccordionTrigger>

                {models.length > 0 && (
                  <AccordionContent>
                    <div className="flex flex-col gap-3 pt-3 pl-8">
                      {models.map((model) => (
                        <div key={model} className="flex items-center gap-3">
                          <Checkbox
                            id={`${item.label}-${model}`}
                            checked={activeModelsForCategory.includes(model)}
                            onCheckedChange={() => handleModelToggle(item.label, model)}
                            className="h-4 w-4 rounded border-gray-300 data-[state=checked]:border-[#3B82F6] data-[state=checked]:bg-[#3B82F6]"
                          />
                          <label
                            htmlFor={`${item.label}-${model}`}
                            className="cursor-pointer text-sm font-medium text-gray-700 select-none"
                          >
                            {model}
                          </label>
                        </div>
                      ))}
                    </div>
                  </AccordionContent>
                )}
              </AccordionItem>
            );
          })}
        </Accordion>
      </div>
    );
  };

  useEffect(() => {
    if (error) {
      const timer = setTimeout(clearError, 5000);
      return () => clearTimeout(timer);
    }
  }, [error, clearError]);

  if (isLoading && !isInitialized) {
    return (
      <div className="p-3 md:p-4">
        <div className="animate-pulse">
          <div className="mb-2 h-3 w-3/4 rounded bg-gray-200 md:h-4"></div>
          <div className="mb-2 h-3 w-1/2 rounded bg-gray-200 md:h-4"></div>
          <div className="h-3 w-2/3 rounded bg-gray-200 md:h-4"></div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="rounded border border-red-200 bg-red-50 p-3 md:p-4">
        <p className="text-xs text-red-700 md:text-sm">
          {t('error')}: {error}
        </p>
        <button
          onClick={() => {
            clearError();
            fetchFilterMetadata();
          }}
          className="mt-2 rounded bg-red-600 px-3 py-1 text-xs text-white hover:bg-red-700 md:text-sm"
        >
          {t('retry')}
        </button>
      </div>
    );
  }

  if (!filterMetadata) {
    return <div className="p-4 text-gray-500">{t('noData')}</div>;
  }

  return (
    <div className="w-full bg-white p-4">
      {filterMetadata.bodyTypes &&
        filterMetadata.bodyTypes.length > 0 &&
        renderFilterSection(
          t('byBodyTypes'),
          filterMetadata.bodyTypes.map((b) => ({ label: b.bodyType, count: b.count, models: b.models })),
          'bodyType',
        )}

      {filterMetadata.brands &&
        filterMetadata.brands.length > 0 &&
        renderFilterSection(
          t('byBrands'),
          filterMetadata.brands.map((b) => ({ label: b.make, count: b.count, models: b.models })),
          'brand',
        )}
    </div>
  );
};

export default CarFilter;
